package com.nextrade.persistence.repository; import com.nextrade.persistence.entity.EmailVerificationEntity; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*; import java.time.*; public interface EmailVerificationJpaRepository extends JpaRepository<EmailVerificationEntity,UUID> { @Modifying @Query("update EmailVerificationEntity e set e.used=true,e.usedAt=:now where e.selector=:selector and e.codeDigest=:digest and e.used=false and e.expiresAt>:now and e.attempts<e.maxAttempts") int consumeAtomically(@Param("selector") String selector,@Param("digest") String digest,@Param("now") Instant now); Optional<EmailVerificationEntity> findBySelector(String selector); }